<?php
declare(strict_types=1);require_once __DIR__.'/includes/ui.php';pv_require_login();$db=pv_db();$uid=(int)$_SESSION['myid'];$notice='';$error='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){try{pv_require_csrf();$slot=max(1,min(6,(int)($_POST['slot']??1)));if(isset($_POST['remove']))dn_remove_party_slot($db,$uid,$slot);else{$id=(int)($_POST['digimon_id']??0);if($id<=0)throw new RuntimeException('Choose a Digimon.');dn_assign_party_slot($db,$uid,$slot,$id);}$notice='Party link updated.';}catch(Throwable $e){$error=$e->getMessage();}}
$party=dn_party_rows($db,$uid);$collection=dn_collection_rows($db,$uid);pv_page_start('Active Party','party.php',true);
?>
<div class="pv-game-layout"><?php pv_game_side_menu('party.php');?><main class="pv-main-column"><section class="pv-page"><div class="pv-page-head"><?php nxt_page_sprites();?><div><span class="pv-eyebrow">BATTLE LINK // THREE ACTIVE · THREE RESERVE</span><h1>Active Party</h1><p class="pv-subtle">The first three available partners enter battle. Keep up to three more in reserve and switch them in when needed. HP and SP fully recover after every battle.</p></div></div><?php if($notice):?><div class="pv-flash success"><?=pv_h($notice)?></div><?php endif;?><?php if($error):?><div class="pv-flash error"><?=pv_h($error)?></div><?php endif;?><div class="dn-party-grid"><?php for($slot=1;$slot<=6;$slot++):$d=$party[$slot]??null;?><section class="dn-party-slot"><small><?=$slot<=3?'FRONT LINE':'RESERVE'?> · SLOT <?=$slot?></small><?php if($d)echo dn_digimon_card($d);?><form method="post" style="margin-top:10px"><?=pv_csrf_field()?><input type="hidden" name="slot" value="<?=$slot?>"><select name="digimon_id"><option value="">Choose Digimon…</option><?php foreach($collection as $c):?><option value="<?=(int)$c['id']?>" <?=($d&&(int)$d['id']===(int)$c['id'])?'selected':''?>><?=pv_h((string)($c['nickname']?:$c['name']))?> · Lv. <?=(int)$c['level']?><?=!empty($c['slot'])?' · Slot '.(int)$c['slot']:''?></option><?php endforeach;?></select><div class="pv-actions"><button class="pv-button" type="submit">Assign</button><?php if($d):?><button class="pv-button pv-button-secondary" name="remove" value="1">Clear slot</button><?php endif;?></div></form></section><?php endfor;?></div></section></main></div><?php pv_page_end(); ?>
